using System;using System.Linq;using System.Reflection;using NUnit.Framework;using UnityEngine;namespace Rootborn.Tests.EditMode.UI{public sealed class UrbanGameplayHudLayoutTests{GameObject root;RectTransform clock,energy,focus,guide;Type layout;[SetUp]public void Setup(){layout=typeof(Rootborn.UI.HUD.TimeHud).Assembly.GetType("Rootborn.UI.HUD.UrbanGameplayHudLayout");Assert.That(layout,Is.Not.Null,"Gameplay HUD needs a shared reserved-column layout");root=new GameObject("ReferenceCanvas",typeof(RectTransform));((RectTransform)root.transform).sizeDelta=new Vector2(1920,1080);clock=Make("clock");energy=Make("energy");focus=Make("focus");guide=Make("guide");Place();}[TearDown]public void Cleanup(){if(root!=null)UnityEngine.Object.DestroyImmediate(root);}RectTransform Make(string name){var g=new GameObject(name,typeof(RectTransform));g.transform.SetParent(root.transform,false);return (RectTransform)g.transform;}void Place(){layout.GetMethod("PositionClock").Invoke(null,new object[]{clock});layout.GetMethod("PositionResource").Invoke(null,new object[]{energy,false});layout.GetMethod("PositionResource").Invoke(null,new object[]{focus,true});layout.GetMethod("PositionTracked").Invoke(null,new object[]{guide});}Rect Bounds(RectTransform r){var c=new Vector3[4];r.GetWorldCorners(c);return new Rect(c[0],c[2]-c[0]);}[Test]public void RightColumnLeavesLeftGameplayAndFarRightControlsClear(){foreach(var r in new[]{clock,energy,focus,guide}){Assert.That(Bounds(r).xMin,Is.GreaterThanOrEqualTo(0),r.name+" must leave the left half gameplay unobscured");Assert.That(Bounds(r).xMax,Is.LessThanOrEqualTo(960-204),r.name+" must reserve far-right edge controls");}}[Test]public void ClockResourcesAndTrackedGuideDoNotOverlap(){var all=new[]{clock,energy,focus,guide};for(int i=0;i<all.Length;i++)for(int j=i+1;j<all.Length;j++)Assert.That(Bounds(all[i]).Overlaps(Bounds(all[j])),Is.False,all[i].name+" overlaps "+all[j].name);Assert.That(Bounds(guide).yMax,Is.LessThan(Bounds(clock).yMin));}[Test]public void ReinstallAndResizeKeepAnchorsSizesAndRightInset(){var prior=new[]{clock,energy,focus,guide}.Select(Bounds).ToArray();Place();for(int n=0;n<4;n++)Assert.That(Bounds(new[]{clock,energy,focus,guide}[n]),Is.EqualTo(prior[n]));((RectTransform)root.transform).sizeDelta=new Vector2(2560,1440);Assert.That(1280-Bounds(focus).xMax,Is.EqualTo(204).Within(.01));Assert.That(Bounds(clock).size,Is.EqualTo(new Vector2(420,144)));Assert.That(guide.sizeDelta.x,Is.GreaterThanOrEqualTo(640));Assert.That(guide.anchorMin,Is.EqualTo(Vector2.one));}}}
